window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f9ecdc55483e6a14"]={"versions": [{"id": "FIG-f9ecdc55483e6a14", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> PDU-/Header-Bitlayout (Protokoll-Mapping-Diagramm auf Bit- und Byte-Ebene).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der genauen Serialisierungsreihenfolge und Bit-Positionierung des 16-Bit-Header-Abschnitts für das <strong>AUTOSAR E2E Profile 22</strong> (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Release R24-11) bei einer Basiskonfiguration mit <code>Offset = 0</code>.\n</li><li><strong>Architektur-Einordnung:</strong> Verortung in der AUTOSAR E2E-Bibliothek (Foundation, Classic Platform sowie Adaptive Platform). Dient der Absicherung sicherheitskritischer Kommunikationsdaten (bis ASIL D gemäß ISO 26262) gegen Übertragungsfehler (Verfälschung, Paketverlust, Wiederholung, Einfügung) auf Feldbussen (CAN, CAN FD, FlexRay). In dieser Konfiguration wird die vollständige Bus-Layout-Abwärtskompatibilität zum klassischen E2E Profile 2 hergestellt.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Datenfelder &amp; Bit-Struktur (16 Bit / 2 Byte):</strong>\n<ul class=\"fig-list\"><li><strong>Byte 0 (Transmission Order 0–7 | Bit Order 7–0):</strong>\n<ul class=\"fig-list\"><li><code>E2E CRC</code> (8 Bit): Vollständige Belegung von Byte 0 durch die 8-Bit-Prüfsumme.\n</li></ul>\n</li><li><strong>Byte 1 (Transmission Order 8–15 | Bit Order 15–8):</strong>\n<ul class=\"fig-list\"><li><code>Unused / User Data</code> (4 Bit, Transmission Order 8–11 | Bit Order 15–12): Nicht durch den E2E-Header belegt. Steht vollumfänglich für Nutzdaten der Applikation zur Verfügung.\n</li><li><code>Counter</code> (4 Bit, Transmission Order 12–15 | Bit Order 11–8): 4-Bit-Sequenz-/Alive-Zähler im niederwertigen Nibble (bezogen auf die Transmission Order) von Byte 1.\n</li></ul>\n</li></ul>\n</li><li><strong>Serialisierungs- &amp; Ordnungsregime:</strong>\n<ul class=\"fig-list\"><li><strong>Byte Order (Little Endian):</strong> Byte 0 (CRC) wird vor Byte 1 (Nutzdaten/Counter) übertragen.\n</li><li><strong>Bit Order (MSB First):</strong> Innerhalb jedes Bytes wird das Most Significant Bit zuerst gesendet (FlexRay-/CAN-Bus-Standard). Byte 0: Bit 7 (MSB) zu Bit 0 (LSB). Byte 1: Bit 15 (MSB) zu Bit 8 (LSB).\n</li></ul>\n</li><li><strong>Metamodell-Bezug:</strong> Entspricht der Allokation innerhalb einer <code>ISignalIPdu</code> bzw. Signal-Group im ARXML-Metamodell. Die Zuordnung erfolgt über die E2E-Konfigurationsstruktur (<code>E2E_P22ConfigType</code>) mit Parameter <code>Offset = 0</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sender-Pfad (<code>E2E_P22Protect</code>):</strong>\n<ol class=\"fig-list\"><li>Inkrementierung des internen 4-Bit-Counters (<code>Counter = (Counter + 1) % 15</code> bzw. modulo Konfiguration) im Status-Objekt (<code>E2E_P22ProtectStateType</code>).\n</li><li>Schreiben des Zählerwertes in die Bits 12–15 (Transmission Order) von Byte 1 unter strikter Maskierung, um die 4 Bits Nutzdaten (Bits 8–11) nicht zu verändern.\n</li><li>Berechnung der 8-Bit-CRC über Daten-ID, Nutzdaten und Counter.\n</li><li>Platzieren der berechneten CRC in Byte 0 (Transmission Order 0–7).\n</li></ol>\n</li><li><strong>Empfänger-Pfad (<code>E2E_P22Check</code>):</strong>\n<ol class=\"fig-list\"><li>Deserialisierung: Auslesen von CRC (Byte 0) und Counter (Byte 1, Bits 12–15).\n</li><li>Lokale Neuberechnung der 8-Bit-CRC über Nutzdaten und erwartete Data-ID.\n</li><li>Prüfung: Validierung der empfangenen CRC gegen die berechnete CRC sowie Delta-Prüfung des Counters zur Erkennung von Paketverlust, Wiederholungen oder Jitter.\n</li><li>Rückgabe des Profil-Status (<code>E2E_P22CheckStatusType</code>, z. B. <code>E2E_P22_STATUS_OK</code>, <code>WRONGSEQUENCE</code>, <code>CRCERROR</code>) an RTE/Com; bei persistenter Abweichung Auslösung von Fehlerreaktionen (Dem/Det oder Failsafe-Fallback auf Applikationsebene).\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-Grenzbedingungen:</strong>\n<ul class=\"fig-list\"><li>Die Gesamtlänge der PDU muss zwingend ein Vielfaches von 8 Bit (Full Bytes) sein.\n</li><li>Byte 1 teilt sich E2E-Steuerdaten und Anwendungsdaten: Signal-Packer (Com/RTE) und E2E-Wrapper müssen sicherstellen, dass Schreiboperationen auf den Bits 8–11 und Bits 12–15 isoliert (per Read-Modify-Write bzw. bitweiser Maskierung) erfolgen, um Datenkorruption zu vermeiden.\n</li></ul>\n</li><li><strong>Offset-Flexibilität vs. Abwärtskompatibilität:</strong>\n<ul class=\"fig-list\"><li>Die gezeigte Konfiguration <code>Offset = 0</code> ist zwingende Voraussetzung für Interoperabilität mit existierenden E2E Profile 2 Gegenstellen auf dem Bus.\n</li><li>Ein konfigurierter <code>Offset &gt; 0</code> (immer Vielfaches von 8 Bit) verschiebt diesen 2-Byte-Block innerhalb der PDU und bricht die Profile-2-Kompatibilität.\n</li></ul>\n</li><li><strong>API-Vertrag (<code>PRS_E2E_00523</code>):</strong>\n<ul class=\"fig-list\"><li>Der Alive-Counter wird ausschließlich autonom durch die E2E-Bibliotheksfunktionen initialisiert, inkrementiert, zurückgesetzt und verifiziert. Der Aufrufer (Applikation/SWC) darf keinen direkten schreibenden oder manipulierenden Zugriff auf den Counter ausführen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-7eea8ed0a005a4c8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> PDU-/Header-Bitlayout (Protokoll-Mapping-Diagramm auf Bit- und Byte-Ebene).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der genauen Serialisierungsreihenfolge und Bit-Positionierung des 16-Bit-Header-Abschnitts für das <strong>AUTOSAR E2E Profile 22</strong> (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Release R24-11) bei einer Basiskonfiguration mit <code>Offset = 0</code>.\n</li><li><strong>Architektur-Einordnung:</strong> Verortung in der AUTOSAR E2E-Bibliothek (Foundation, Classic Platform sowie Adaptive Platform). Dient der Absicherung sicherheitskritischer Kommunikationsdaten (bis ASIL D gemäß ISO 26262) gegen Übertragungsfehler (Verfälschung, Paketverlust, Wiederholung, Einfügung) auf Feldbussen (CAN, CAN FD, FlexRay). In dieser Konfiguration wird die vollständige Bus-Layout-Abwärtskompatibilität zum klassischen E2E Profile 2 hergestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Datenfelder &amp; Bit-Struktur (16 Bit / 2 Byte):</strong>\n<ul class=\"fig-list\"><li><strong>Byte 0 (Transmission Order 0–7 | Bit Order 7–0):</strong>\n<ul class=\"fig-list\"><li><code>E2E CRC</code> (8 Bit): Vollständige Belegung von Byte 0 durch die 8-Bit-Prüfsumme.\n</li></ul>\n</li><li><strong>Byte 1 (Transmission Order 8–15 | Bit Order 15–8):</strong>\n<ul class=\"fig-list\"><li><code>Unused / User Data</code> (4 Bit, Transmission Order 8–11 | Bit Order 15–12): Nicht durch den E2E-Header belegt. Steht vollumfänglich für Nutzdaten der Applikation zur Verfügung.\n</li><li><code>Counter</code> (4 Bit, Transmission Order 12–15 | Bit Order 11–8): 4-Bit-Sequenz-/Alive-Zähler im niederwertigen Nibble (bezogen auf die Transmission Order) von Byte 1.\n</li></ul>\n</li></ul>\n</li><li><strong>Serialisierungs- &amp; Ordnungsregime:</strong>\n<ul class=\"fig-list\"><li><strong>Byte Order (Little Endian):</strong> Byte 0 (CRC) wird vor Byte 1 (Nutzdaten/Counter) übertragen.\n</li><li><strong>Bit Order (MSB First):</strong> Innerhalb jedes Bytes wird das Most Significant Bit zuerst gesendet (FlexRay-/CAN-Bus-Standard). Byte 0: Bit 7 (MSB) zu Bit 0 (LSB). Byte 1: Bit 15 (MSB) zu Bit 8 (LSB).\n</li></ul>\n</li><li><strong>Metamodell-Bezug:</strong> Entspricht der Allokation innerhalb einer <code>ISignalIPdu</code> bzw. Signal-Group im ARXML-Metamodell. Die Zuordnung erfolgt über die E2E-Konfigurationsstruktur (<code>E2E_P22ConfigType</code>) mit Parameter <code>Offset = 0</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sender-Pfad (<code>E2E_P22Protect</code>):</strong>\n<ol class=\"fig-list\"><li>Inkrementierung des internen 4-Bit-Counters (<code>Counter = (Counter + 1) % 15</code> bzw. modulo Konfiguration) im Status-Objekt (<code>E2E_P22ProtectStateType</code>).\n</li><li>Schreiben des Zählerwertes in die Bits 12–15 (Transmission Order) von Byte 1 unter strikter Maskierung, um die 4 Bits Nutzdaten (Bits 8–11) nicht zu verändern.\n</li><li>Berechnung der 8-Bit-CRC über Daten-ID, Nutzdaten und Counter.\n</li><li>Platzieren der berechneten CRC in Byte 0 (Transmission Order 0–7).\n</li></ol>\n</li><li><strong>Empfänger-Pfad (<code>E2E_P22Check</code>):</strong>\n<ol class=\"fig-list\"><li>Deserialisierung: Auslesen von CRC (Byte 0) und Counter (Byte 1, Bits 12–15).\n</li><li>Lokale Neuberechnung der 8-Bit-CRC über Nutzdaten und erwartete Data-ID.\n</li><li>Prüfung: Validierung der empfangenen CRC gegen die berechnete CRC sowie Delta-Prüfung des Counters zur Erkennung von Paketverlust, Wiederholungen oder Jitter.\n</li><li>Rückgabe des Profil-Status (<code>E2E_P22CheckStatusType</code>, z. B. <code>E2E_P22_STATUS_OK</code>, <code>WRONGSEQUENCE</code>, <code>CRCERROR</code>) an RTE/Com; bei persistenter Abweichung Auslösung von Fehlerreaktionen (Dem/Det oder Failsafe-Fallback auf Applikationsebene).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-Grenzbedingungen:</strong>\n<ul class=\"fig-list\"><li>Die Gesamtlänge der PDU muss zwingend ein Vielfaches von 8 Bit (Full Bytes) sein.\n</li><li>Byte 1 teilt sich E2E-Steuerdaten und Anwendungsdaten: Signal-Packer (Com/RTE) und E2E-Wrapper müssen sicherstellen, dass Schreiboperationen auf den Bits 8–11 und Bits 12–15 isoliert (per Read-Modify-Write bzw. bitweiser Maskierung) erfolgen, um Datenkorruption zu vermeiden.\n</li></ul>\n</li><li><strong>Offset-Flexibilität vs. Abwärtskompatibilität:</strong>\n<ul class=\"fig-list\"><li>Die gezeigte Konfiguration <code>Offset = 0</code> ist zwingende Voraussetzung für Interoperabilität mit existierenden E2E Profile 2 Gegenstellen auf dem Bus.\n</li><li>Ein konfigurierter <code>Offset &gt; 0</code> (immer Vielfaches von 8 Bit) verschiebt diesen 2-Byte-Block innerhalb der PDU und bricht die Profile-2-Kompatibilität.\n</li></ul>\n</li><li><strong>API-Vertrag (<code>PRS_E2E_00523</code>):</strong>\n<ul class=\"fig-list\"><li>Der Alive-Counter wird ausschließlich autonom durch die E2E-Bibliotheksfunktionen initialisiert, inkrementiert, zurückgesetzt und verifiziert. Der Aufrufer (Applikation/SWC) darf keinen direkten schreibenden oder manipulierenden Zugriff auf den Counter ausführen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-f9ecdc55483e6a14", "to": "FIG-7eea8ed0a005a4c8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
